#!/usr/bin/env node
/**
 * search_flights.js
 *
 * Queries the Amadeus Flight Offers API for direct (non-stop) flights
 * and saves results to a CSV file.
 *
 * Usage:
 *   node scripts/search_flights.js --origin JFK --destination LAX --date 2025-03-15
 *
 * Environment variables (required):
 *   AMADEUS_API_KEY      - Your Amadeus API key
 *   AMADEUS_API_SECRET   - Your Amadeus API secret
 *
 * Optional flags:
 *   --adults <n>         - Number of adult passengers (default: 1)
 *   --currency <code>    - Currency code, e.g. USD, EUR (default: USD)
 *   --output <path>      - Output CSV path (default: data/sales_q3.csv)
 *   --max <n>            - Max number of results (default: 50)
 */

const https = require("https");
const fs = require("fs");
const path = require("path");

// ---------------------------------------------------------------------------
// Argument parsing
// ---------------------------------------------------------------------------
function parseArgs(argv) {
  const args = {};
  for (let i = 2; i < argv.length; i++) {
    if (argv[i].startsWith("--")) {
      const key = argv[i].slice(2);
      const val = argv[i + 1] && !argv[i + 1].startsWith("--") ? argv[i + 1] : true;
      args[key] = val;
      if (val !== true) i++;
    }
  }
  return args;
}

const args = parseArgs(process.argv);

const ORIGIN = args.origin;
const DESTINATION = args.destination;
const DATE = args.date;
const ADULTS = args.adults || "1";
const CURRENCY = args.currency || "USD";
const OUTPUT = args.output || "data/sales_q3.csv";
const MAX_RESULTS = args.max || "50";

const API_KEY = process.env.AMADEUS_API_KEY;
const API_SECRET = process.env.AMADEUS_API_SECRET;

// ---------------------------------------------------------------------------
// Validation
// ---------------------------------------------------------------------------
function exitWithError(msg) {
  console.error(`❌ Error: ${msg}`);
  process.exit(1);
}

if (!ORIGIN) exitWithError("--origin is required (e.g. --origin JFK)");
if (!DESTINATION) exitWithError("--destination is required (e.g. --destination LAX)");
if (!DATE) exitWithError("--date is required (e.g. --date 2025-03-15)");
if (!/^\d{4}-\d{2}-\d{2}$/.test(DATE)) exitWithError("--date must be in YYYY-MM-DD format");
if (!API_KEY) exitWithError("AMADEUS_API_KEY environment variable is not set");
if (!API_SECRET) exitWithError("AMADEUS_API_SECRET environment variable is not set");

// ---------------------------------------------------------------------------
// HTTPS helper (no external dependencies)
// ---------------------------------------------------------------------------
function request(options, body) {
  return new Promise((resolve, reject) => {
    const req = https.request(options, (res) => {
      const chunks = [];
      res.on("data", (d) => chunks.push(d));
      res.on("end", () => {
        const raw = Buffer.concat(chunks).toString();
        try {
          resolve({ status: res.statusCode, data: JSON.parse(raw) });
        } catch {
          reject(new Error(`Non-JSON response (${res.statusCode}): ${raw.slice(0, 500)}`));
        }
      });
    });
    req.on("error", reject);
    if (body) req.write(body);
    req.end();
  });
}

// ---------------------------------------------------------------------------
// Amadeus OAuth2 token
// ---------------------------------------------------------------------------
async function getAccessToken() {
  const postData = `grant_type=client_credentials&client_id=${encodeURIComponent(API_KEY)}&client_secret=${encodeURIComponent(API_SECRET)}`;
  const { status, data } = await request(
    {
      hostname: "api.amadeus.com",
      path: "/v1/security/oauth2/token",
      method: "POST",
      headers: {
        "Content-Type": "application/x-www-form-urlencoded",
        "Content-Length": Buffer.byteLength(postData),
      },
    },
    postData
  );

  if (status !== 200 || !data.access_token) {
    exitWithError(`Failed to authenticate with Amadeus (HTTP ${status}): ${JSON.stringify(data)}`);
  }
  return data.access_token;
}

// ---------------------------------------------------------------------------
// Search for direct flights
// ---------------------------------------------------------------------------
async function searchDirectFlights(token) {
  const params = new URLSearchParams({
    originLocationCode: ORIGIN.toUpperCase(),
    destinationLocationCode: DESTINATION.toUpperCase(),
    departureDate: DATE,
    adults: ADULTS,
    nonStop: "true",             // ← direct flights only
    currencyCode: CURRENCY,
    max: MAX_RESULTS,
  });

  const { status, data } = await request({
    hostname: "api.amadeus.com",
    path: `/v2/shopping/flight-offers?${params.toString()}`,
    method: "GET",
    headers: { Authorization: `Bearer ${token}` },
  });

  if (status !== 200) {
    exitWithError(`Flight search failed (HTTP ${status}): ${JSON.stringify(data.errors || data)}`);
  }
  return data;
}

// ---------------------------------------------------------------------------
// Parse API response → flat rows
// ---------------------------------------------------------------------------
function parseOffers(apiResponse) {
  const offers = apiResponse.data || [];
  const dictionaries = apiResponse.dictionaries || {};
  const carriers = dictionaries.carriers || {};

  const rows = [];
  for (const offer of offers) {
    const price = offer.price || {};
    for (const itinerary of offer.itineraries || []) {
      for (const segment of itinerary.segments || []) {
        rows.push({
          offer_id: offer.id,
          airline_code: segment.carrierCode,
          airline_name: carriers[segment.carrierCode] || segment.carrierCode,
          flight_number: `${segment.carrierCode}${segment.number}`,
          origin: segment.departure.iataCode,
          destination: segment.arrival.iataCode,
          departure_time: segment.departure.at,
          arrival_time: segment.arrival.at,
          duration: itinerary.duration || "",
          aircraft: (segment.operating || {}).carrierCode
            ? `${segment.operating.carrierCode}/${(segment.aircraft || {}).code || ""}`
            : (segment.aircraft || {}).code || "",
          cabin: ((offer.travelerPricings || [])[0]?.fareDetailsBySegment?.[0]?.cabin) || "",
          total_price: price.total || "",
          currency: price.currency || CURRENCY,
          seats_available: offer.numberOfBookableSeats || "",
        });
      }
    }
  }
  return rows;
}

// ---------------------------------------------------------------------------
// Write CSV
// ---------------------------------------------------------------------------
function writeCsv(rows, filePath) {
  if (rows.length === 0) {
    console.log("⚠️  No direct flights found for the given criteria.");
    process.exit(0);
  }

  const columns = Object.keys(rows[0]);

  // Escape CSV values
  const escape = (val) => {
    const str = String(val);
    return str.includes(",") || str.includes('"') || str.includes("\n")
      ? `"${str.replace(/"/g, '""')}"`
      : str;
  };

  const lines = [
    columns.join(","),
    ...rows.map((row) => columns.map((col) => escape(row[col])).join(",")),
  ];

  // Ensure output directory exists
  const dir = path.dirname(filePath);
  if (dir && !fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }

  fs.writeFileSync(filePath, lines.join("\n") + "\n", "utf-8");
  console.log(`✅ Saved ${rows.length} flight(s) to ${filePath}`);
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------
async function main() {
  console.log(`🔍 Searching direct flights: ${ORIGIN.toUpperCase()} → ${DESTINATION.toUpperCase()} on ${DATE}`);
  console.log(`   Adults: ${ADULTS} | Currency: ${CURRENCY} | Max results: ${MAX_RESULTS}\n`);

  const token = await getAccessToken();
  const apiResponse = await searchDirectFlights(token);
  const rows = parseOffers(apiResponse);
  writeCsv(rows, OUTPUT);

  // Print a summary table
  console.log("\n📋 Preview (top 5):\n");
  const preview = rows.slice(0, 5);
  console.table(
    preview.map((r) => ({
      Flight: r.flight_number,
      Airline: r.airline_name,
      Departure: r.departure_time,
      Arrival: r.arrival_time,
      Duration: r.duration,
      Price: `${r.total_price} ${r.currency}`,
    }))
  );
}

main().catch((err) => {
  console.error("❌ Unexpected error:", err.message);
  process.exit(1);
});

